# [MODULE DOC] End-to-end tests for chain verification: a mix of proved and declared commits,
# failing proofs (non-zero exit, or exit zero without the pass line), command line exit codes,
# setup errors (unresolvable references, missing proof folder, non-ancestor base, empty range,
# merge commits), concurrent proof execution, and a full flow using a proof folder generated by
# the proof generator for a real move commit.
import sys
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

from cli_testlib import _chain, _commit, _git, _write, _write_stub_proof
from mechanical_refactor_proof_generator import generate_range
from mechanical_refactor_reproduction_cli import (
    VERDICT_FAIL,
    VERDICT_HUMAN_REVIEW,
    VERDICT_PASS,
    ChainVerificationError,
    main,
    verify_chain,
)


def test_chain_of_proved_and_declared_commits_passes(repo: Path, tmp_path: Path) -> None:
    # [FUNCTION DOC] Chain of a mechanical commit (with passing stand-in proof) and a
    # non-mechanical commit. Asserts verdicts in order are pass then human review, and the chain
    # passes.
    """A proved mechanical commit plus a declared non-mechanical one verifies as PASS."""
    proof = tmp_path / "proof"
    base, shas = _chain(
        repo,
        ["mechanical_provable: move foo", "non_mechanical_provable: rework bar"],
    )
    _write_stub_proof(proof, shas[0])

    result = verify_chain(base=base, branch="chain", proof=proof, repo_root=str(repo))

    assert [v.verdict for v in result.verdicts] == [VERDICT_PASS, VERDICT_HUMAN_REVIEW]
    assert result.passed


def test_failing_proof_fails_the_commit_and_the_chain(repo: Path, tmp_path: Path) -> None:
    # [FUNCTION DOC] One mechanical commit whose stand-in proof prints a residual and exits one.
    # Asserts the verdict is fail, the detail text contains the residual word from the output
    # tail, and the chain did not pass.
    """A proof that exits non-zero yields FAIL with the output tail in the detail."""
    proof = tmp_path / "proof"
    base, shas = _chain(repo, ["mechanical_provable: move foo"])
    _write_stub_proof(proof, shas[0], passing=False)

    result = verify_chain(base=base, branch="chain", proof=proof, repo_root=str(repo))

    assert result.verdicts[0].verdict == VERDICT_FAIL
    assert "RESIDUAL" in result.verdicts[0].detail
    assert not result.passed


def test_proof_exiting_zero_without_a_pass_line_is_a_fail(repo: Path, tmp_path: Path) -> None:
    # [FUNCTION DOC] The proof script is overwritten to print a residual line and exit with the
    # default zero status. Asserts the verdict is fail (a pass needs the pass line too).
    """PASS needs exit 0 AND the PASS: verdict line, so a residual under exit 0 fails."""
    proof = tmp_path / "proof"
    base, shas = _chain(repo, ["mechanical_provable: move foo"])
    script = _write_stub_proof(proof, shas[0])
    script.write_text('print("RESIDUAL (1 lines):\\n+x")\n')

    result = verify_chain(base=base, branch="chain", proof=proof, repo_root=str(repo))

    assert result.verdicts[0].verdict == VERDICT_FAIL


def test_main_exit_codes_reflect_the_chain_verdict(repo: Path, tmp_path: Path) -> None:
    # [FUNCTION DOC] Builds a one-commit passing chain and asserts the command line entry point
    # returns 0. Then adds an empty commit with a message lacking any kind word on the chain
    # branch and asserts it now returns 1.
    """main returns 0 for a verified chain and 1 once an unverifiable commit appears."""
    proof = tmp_path / "proof"
    base, shas = _chain(repo, ["mechanical_provable: move"])
    _write_stub_proof(proof, shas[0])
    args = [
        "--base",
        base,
        "--branch",
        "chain",
        "--proof",
        str(proof),
        "--repo-root",
        str(repo),
    ]

    assert main(args) == 0

    _git(repo, "commit", "-q", "--allow-empty", "-m", "plain subject with no kind word")
    assert main(args) == 1


def test_unresolvable_refs_and_missing_proof_folder_are_setup_errors(repo: Path, tmp_path: Path) -> None:
    # [FUNCTION DOC] Asserts the chain error is raised for a non-existent branch name and for a
    # non-existent proof folder, and that the command line entry point returns 2 for the
    # non-existent branch.
    """Bad --base/--branch/--proof inputs raise ChainVerificationError (exit code 2)."""
    proof = tmp_path / "proof"
    proof.mkdir()
    base, _ = _chain(repo, ["mechanical_provable: move"])

    with pytest.raises(ChainVerificationError):
        verify_chain(base=base, branch="no-such-branch", proof=proof, repo_root=str(repo))
    with pytest.raises(ChainVerificationError):
        verify_chain(
            base=base,
            branch="chain",
            proof=tmp_path / "missing",
            repo_root=str(repo),
        )
    assert (
        main(
            [
                "--base",
                base,
                "--branch",
                "no-such-branch",
                "--proof",
                str(proof),
                "--repo-root",
                str(repo),
            ]
        )
        == 2
    )


def test_non_ancestor_base_and_empty_range_are_setup_errors(repo: Path, tmp_path: Path) -> None:
    # [FUNCTION DOC] Builds a chain branch, then switches to the main branch and commits an
    # unrelated file there. Asserts the chain error is raised when the base is that main-side
    # commit (not an ancestor of the chain branch) and when base and branch are the same commit
    # (empty range).
    """A base off the branch or an empty base..branch range refuses to verify."""
    proof = tmp_path / "proof"
    proof.mkdir()
    base, shas = _chain(repo, ["mechanical_provable: move"])
    _git(repo, "switch", "-q", "main")
    _write(repo, **{"other.py": "OTHER = 1\n"})
    off_branch = _commit(repo, "unrelated main-side commit")

    with pytest.raises(ChainVerificationError):
        verify_chain(base=off_branch, branch="chain", proof=proof, repo_root=str(repo))
    with pytest.raises(ChainVerificationError):
        verify_chain(base=shas[0], branch=shas[0], proof=proof, repo_root=str(repo))


def test_merge_commit_in_the_chain_is_a_setup_error(repo: Path, tmp_path: Path) -> None:
    # [FUNCTION DOC] Builds a chain branch, adds a commit on the main branch, then merges main
    # into the chain branch with a merge commit (no fast-forward). Asserts verifying the chain
    # raises the chain error because the range contains a merge commit.
    """A non-linear chain (contains a merge commit) refuses to verify."""
    proof = tmp_path / "proof"
    proof.mkdir()
    base, _ = _chain(repo, ["mechanical_provable: move"])
    _git(repo, "switch", "-q", "main")
    _write(repo, **{"other.py": "OTHER = 1\n"})
    _commit(repo, "mechanical_provable: main-side")
    _git(repo, "switch", "-q", "chain")
    _git(repo, "merge", "-q", "--no-ff", "-m", "non_mechanical_provable: merge", "main")

    with pytest.raises(ChainVerificationError):
        verify_chain(base=base, branch="chain", proof=proof, repo_root=str(repo))


def test_proofs_run_concurrently_up_to_jobs(repo: Path, tmp_path: Path) -> None:
    # [FUNCTION DOC] Two mechanical commits. The first commit's proof polls (up to thirty
    # seconds) for a sentinel file and then passes, exiting one on timeout; the second commit's
    # proof creates the sentinel file and passes. Verifies with two jobs. Asserts both verdicts
    # are pass, the verdict order matches the chain order, and the chain passes (which can only
    # happen if the proofs ran at the same time).
    """With jobs>=2 a proof that waits on a sibling proof's sentinel still completes."""
    proof = tmp_path / "proof"
    sentinel = tmp_path / "sentinel"
    base, shas = _chain(repo, ["mechanical_provable: move a", "mechanical_provable: move b"])
    waiter = _write_stub_proof(proof, shas[0])
    waiter.write_text(
        "import sys, time\n"
        f"deadline = time.monotonic() + 30\n"
        f"while not __import__('pathlib').Path({str(sentinel)!r}).exists():\n"
        "    if time.monotonic() > deadline:\n"
        "        sys.exit(1)\n"
        "    time.sleep(0.05)\n"
        'print("PASS: reproduces the commit byte-for-byte.")\n'
        "sys.exit(0)\n"
    )
    creator = _write_stub_proof(proof, shas[1])
    creator.write_text(
        "import sys\n"
        f"__import__('pathlib').Path({str(sentinel)!r}).write_text('go')\n"
        'print("PASS: reproduces the commit byte-for-byte.")\n'
        "sys.exit(0)\n"
    )

    result = verify_chain(base=base, branch="chain", proof=proof, repo_root=str(repo), jobs=2)

    assert [v.verdict for v in result.verdicts] == [VERDICT_PASS, VERDICT_PASS]
    assert [v.sha for v in result.verdicts] == shas
    assert result.passed


def test_end_to_end_with_a_generated_proof_folder(repo: Path, tmp_path: Path) -> None:
    # [FUNCTION DOC] Base commit: model with keep and resolve, util importing os. Then on a new
    # branch named chain, a commit with the message marked mechanical that moves resolve to util
    # with the primitives' exact output. Generates proofs for the range with the proof generator,
    # verifies the chain against that folder, and asserts the single verdict is for the move
    # commit, is pass, and the chain passes.
    """A real move commit proved by generate_range verifies through the CLI end-to-end."""
    _write(
        repo,
        **{
            "model.py": "def keep():\n    return 0\n\n\ndef resolve(m):\n    return m\n",
            "util.py": "import os\n",
        },
    )
    base = _commit(repo, "base")
    _git(repo, "switch", "-q", "-c", "chain")
    # The after-state is the primitives' exact output (this bare repo has no formatter
    # to absorb the cut's leftover blank lines, unlike a pre-commit-clean real repo).
    _write(
        repo,
        **{
            "model.py": "def keep():\n    return 0\n\n\n",
            "util.py": "import os\n\ndef resolve(m):\n    return m\n",
        },
    )
    move_sha = _commit(repo, "mechanical_provable: move resolve to util")

    proof = tmp_path / "proof"
    generate_range(f"{base}..chain", out_dir=str(proof), repo_root=str(repo))
    result = verify_chain(base=base, branch="chain", proof=proof, repo_root=str(repo))

    assert result.verdicts[0].sha == move_sha
    assert result.verdicts[0].verdict == VERDICT_PASS
    assert result.passed
